def _extract_openaire_validation(self, article_payload: Dict[str, Any]) -> Dict[str, Any]:
    if not self.openaire_schema_tree:
        return {"schema_loaded": False, "missing_mandatory": [], "compatibility_notes": [], "notes": []}

    missing: List[str] = []
    fields = self.openaire_schema_tree.get("fields", [])
    field_lookup = {f.get("field"): f for f in fields}

    def present(value: Any) -> bool:
        if value is None or value == "":
            return False
        if isinstance(value, list):
            return len(value) > 0
        if isinstance(value, dict):
            return any(present(v) for v in value.values())
        return True

    presence_map = {
        "Title": article_payload["title"].get("datacite:title"),
        "Creator": article_payload.get("creators"),
        "Publication Date": article_payload.get("datesByType", {}).get("Issued"),
        "Resource Type": article_payload.get("resourceType"),
        "Resource Identifier": article_payload.get("resourceIdentifier"),
        "Access Rights": article_payload.get("accessRights"),
    }
    for field_name, value in presence_map.items():
        field_def = field_lookup.get(field_name)
        if field_def and field_def.get("requirement") == "M" and not present(value):
            missing.append(field_name)
            self._warn(
                code=f"MISSING_MANDATORY_{field_name.upper().replace(' ', '_')}",
                message=f"Campo mandatory mancante secondo lo schema OpenAIRE: {field_name}",
                function_name="_extract_openaire_validation",
                context={"field_name": field_name},
            )

    compatibility_notes: List[str] = []
    date_types = [d.get("dateType") for d in article_payload.get("dates", [])]
    invalid_types = [t for t in date_types if t not in {"Accepted", "Available", "Issued"}]
    if invalid_types:
        compatibility_notes.append(f"Sono presenti dateType fuori dal profilo export desiderato: {invalid_types}")
        self._warn(
            code="EXPORT_DATE_TYPES_OUTSIDE_PROFILE",
            message=f"Sono presenti dateType fuori dal profilo export desiderato: {invalid_types}",
            function_name="_extract_openaire_validation",
            context={"date_types": date_types},
        )
    if not article_payload.get("datesByType", {}).get("Available") and article_payload.get("datesByType", {}).get("Issued"):
        compatibility_notes.append("Available era assente ed è stato colmato con Issued.")

    return {
        "schema_loaded": True,
        "schema_profile_name": self.openaire_schema_tree.get("profile"),
        "missing_mandatory": missing,
        "compatibility_notes": compatibility_notes,
        "notes": [
            "Validation is limited to high-confidence mandatory field presence checks and export-profile compatibility checks.",
            "The JSON may retain richer internal data outside the direct OpenAIRE export slice.",
        ],
    }
